#!/usr/bin/env Rscript
# Format manuscript tables from existing R estimation outputs.
# Numerical cells are projected verbatim; no model is fitted here.
args <- grep("^--file=", commandArgs(trailingOnly = FALSE), value = TRUE)
root <- if (length(args)) normalizePath(file.path(dirname(sub("^--file=", "", args[1])), "..")) else normalizePath(getwd())
src <- file.path(root, "output", "tables")
dest <- file.path(src, "manuscript")
dir.create(dest, recursive = TRUE, showWarnings = FALSE)
read_source <- function(name) paste(readLines(file.path(src, name), encoding = "UTF-8", warn = FALSE), collapse = "\n")
line_cells <- function(line) {
  line <- trimws(line)
  if (endsWith(line, "\\\\")) line <- substr(line, 1L, nchar(line) - 2L)
  trimws(strsplit(line, "(?<!\\\\)&", perl = TRUE)[[1]])
}
row_text <- function(cells) paste0(paste(cells, collapse = " & "), " \\\\")
pick <- function(text, prefix, indices, label = NULL, se = FALSE) {
  lines <- strsplit(text, "\n", fixed = TRUE)[[1]]
  hits <- which(startsWith(trimws(lines), prefix))
  if (length(hits) != 1L) stop("Expected one row for: ", prefix)
  cells <- line_cells(lines[hits])
  if (any(indices + 1L > length(cells))) stop("Column missing for: ", prefix)
  rows <- row_text(c(if (is.null(label)) cells[1] else label, cells[indices + 1L]))
  if (se) {
    cells <- line_cells(lines[hits + 1L])
    rows <- c(rows, row_text(c("", cells[indices + 1L])))
  }
  rows
}
manifest <- data.frame(output = character(), source = character(), source_md5 = character(), output_md5 = character())
record <- function(stem, sources) {
  output <- file.path(dest, paste0(stem, ".tex"))
  for (name in sources) manifest <<- rbind(manifest, data.frame(output = basename(output), source = name,
    source_md5 = unname(tools::md5sum(file.path(src, name))), output_md5 = unname(tools::md5sum(output))))
}
render <- function(stem, spec, rows, sources = spec$source) {
  lines <- c(paste0("% Generated by code/build_manuscript_exhibits.R; numerical cells copied from ", paste(sources, collapse = ", ")),
    "\\begin{table}[!htbp]", "\\centering", "\\begin{threeparttable}",
    paste0("\\caption{", spec$caption, "}"), paste0("\\label{", spec$label, "}"),
    "\\setstretch{1}", "\\small", "\\setlength{\\tabcolsep}{5pt}", "\\renewcommand{\\arraystretch}{1.15}",
    paste0("\\begin{tabular}{@{}l", paste(rep("c", length(spec$headers) - 1L), collapse = ""), "@{}}"),
    "\\toprule", row_text(spec$headers), "\\midrule", rows, "\\bottomrule", "\\end{tabular}",
    "\\begin{tablenotes}[flushleft]", "\\small",
    paste0("\\item Notes: ", spec$note, " $^{*}p<0.10$, $^{**}p<0.05$, $^{***}p<0.01$."),
    "\\end{tablenotes}", "\\end{threeparttable}", "\\end{table}")
  writeLines(lines, file.path(dest, paste0(stem, ".tex")), useBytes = TRUE)
  record(stem, sources)
}
layout_copy <- function(stem, name, replacements = list(), note = NULL, remove_prefixes = character()) {
  text <- read_source(name)
  text <- gsub("\\scriptsize", "\\small", text, fixed = TRUE)
  for (pair in replacements) {
    if (!grepl(pair[1], text, fixed = TRUE)) stop("Missing layout anchor: ", name, " / ", pair[1])
    text <- gsub(pair[1], pair[2], text, fixed = TRUE)
  }
  if (length(remove_prefixes)) {
    lines <- strsplit(text, "\n", fixed = TRUE)[[1]]
    text <- paste(lines[!vapply(lines, function(x) any(startsWith(x, remove_prefixes)), logical(1))], collapse = "\n")
  }
  if (!is.null(note)) {
    start <- regexpr("\\item \\textit{Note:}", text, fixed = TRUE)[1]
    ending <- regexpr("\n\\end{tablenotes}", text, fixed = TRUE)[1]
    if (start > 0L && ending > start) text <- paste0(substr(text, 1L, start - 1L), "\\item \\textit{Note:} ", note, substr(text, ending, nchar(text)))
  }
  writeLines(text, file.path(dest, paste0(stem, ".tex")), useBytes = TRUE)
  record(stem, name)
}
spec_city_results <- list(source="city_year_cs_twfe_main_table.tex", caption="Procurement, Government Wins, and Appeals", label="tab:city_year_cs_twfe", headers=c("", "\\shortstack{Government win\\\\(1)}", "\\shortstack{Government win\\\\(2)}", "\\shortstack{Appeal\\\\(3)}", "\\shortstack{Appeal\\\\(4)}"), note="CS reports group-time effects aggregated across treated observations, using never-adopting cities as controls. TWFE includes city and year effects. Both use population, GDP, and registered-lawyer covariates; win models also include published-decision coverage. Standard errors are clustered by city. Recorded case counts are examined separately because of timing and disclosure limitations.")
spec_counsel_participation <- list(source="admin_first_stage_counsel_table.tex", caption="Procurement and Government Counsel Participation", label="tab:admin_first_stage_counsel", headers=c("", "\\shortstack{Case level\\\\TWFE}", "\\shortstack{City-year\\\\TWFE}", "\\shortstack{City-year\\\\CS}"), note="The outcome is lawyer representation of the government, recorded in the core panels. The case model includes court, year, and cause effects, plaintiff entity status, and opposing counsel; errors are clustered by city and court. City models use population, GDP, and registered lawyers; errors are clustered by city. CS uses never-adopting controls. Contracted-firm identities are excluded from this specification.")
spec_firm_expansion <- list(source="firm_caseload_expansion_table.tex", caption="Private Caseload, Firm Size, and Client Composition", label="tab:firm_caseload_expansion", headers=c("", "\\shortstack{All civil\\\\cases}", "\\shortstack{Enterprise\\\\cases}", "\\shortstack{Individual\\\\cases}", "\\shortstack{Log number\\\\of lawyers}", "\\shortstack{Enterprise\\\\share}"), note="The first three outcomes are log(1+cases), including zero counts; they measure recorded litigation, not unique clients or revenue. Firm-year comparisons use event years $[-5,5]$, firm-by-tender and tender-by-year effects. Enterprise share requires positive civil case volume. Pre-award means use the specified outcome transformation. Standard errors are clustered by firm and tender.")
spec_private_cases <- list(source="document_mechanism_pure_private_placebo_table.tex", caption="Litigation Returns in Disputes between Private Individuals", label="tab:document_mechanism_pure_private_placebo", headers=c("", "Civil win", "Fee-based win"), note="Both parties are individuals. Models retain firm, tender-by-year, cause-by-side, court, and year-by-lawyer-attribute effects, opposing-counsel and lawyer-experience controls. Outcomes use decisive cases and, for the fee measure, observed fee allocation. Standard errors are clustered by firm and tender. These gains extend beyond government cases, but may still reflect favoritism toward the firm.")
spec_prior_court_exposure <- list(source="document_level_strict_ddd_main_table.tex", caption="Do Returns Concentrate in Courts of Prior Government Work?", label="tab:document_level_strict_ddd_main", headers=c("", "Civil win", "Fee-based win"), note="Prior work means government representation in the same court. Models include all lower-order interactions. Fixed effects cover firm, tender-by-year, court-by-year, cause-by-side, and year-by-lawyer attributes; observed case and experience controls also enter. The sample retains unexposed firms and firms with civil activity in the court before government representation. Errors are clustered by firm and court. Imprecise triple interactions do not show that the effects are equal.")
spec_withdrawal_coding <- list(source="admin_withdrawal_coding_table.tex", caption="Government Outcomes under Alternative Withdrawal Coding", label="tab:admin_withdrawal_coding", headers=c("", "\\shortstack{Baseline\\\\government win}", "\\shortstack{No withdrawal\\\\counted as win}", "\\shortstack{Withdrawals\\\\excluded}", "\\shortstack{Plaintiff\\\\win}"), note="All models use court, year, and cause effects with government counsel, opposing counsel, and plaintiff entity controls; errors are clustered by city and court. The first two columns change the outcome definition; the third changes the sample. Their coefficients are not causal bounds. The supplementary withdrawal-reason labels are derived from these outcome codes, not independently observed motives.")
spec_city_controls <- list(source="city_year_fe_controls_robustness_table.tex", caption="City Outcomes under Alternative Covariates and Time Effects", label="tab:city_year_fe_controls_robustness", headers=c("", "Baseline", "\\shortstack{No\\\\covariates}", "\\shortstack{Lagged\\\\covariates}", "\\shortstack{Province\\\\by year}"), note="All specifications include city effects. The first three include year effects; the last replaces them with province-by-year effects. Baseline covariates are population, GDP, and registered lawyers, plus published-decision coverage for government wins. Lagged covariates shorten the sample. Standard errors are clustered by city.")
spec_alternative_estimators <- list(source="city_year_alternative_estimators_appendix_table.tex", caption="Alternative Staggered-Adoption Estimators", label="tab:city_year_alternative_estimators_appendix", headers=c("Outcome", "TWFE", "CS", "SA"), note="CS is the group-time estimator of \\textcite{callaway2021difference}; SA is the interaction-weighted estimator of \\textcite{sun2021estimating}. All models use the main city covariates and 2,256 city-years. Standard errors are clustered by city. The recorded-count estimates retain the synthetic 2013 pre-period and are diagnostic rather than a headline filing effect; descriptive Panel A intentionally summarizes 2014--2020.")

s <- read_source(spec_city_results$source)
rows <- c(row_text(c("Estimator", "CS", "TWFE", "CS", "TWFE")),
  pick(s, "Treatment $\\times$ Post", 1:4, se = TRUE), pick(s, "Observations", 1:4))
render("city_results", spec_city_results, rows)
s <- read_source(spec_counsel_participation$source); idx <- c(1, 4, 5)
render("counsel_participation", spec_counsel_participation, c(pick(s, "Treatment $\\times$ Post", idx, se = TRUE), pick(s, "Pre-procurement mean", idx), pick(s, "Observations", idx)))
s <- read_source(spec_private_cases$source)
render("private_cases", spec_private_cases, c(pick(s, "Winner $\\times$ Post", 3:4, se = TRUE), pick(s, "Observations", 3:4)))
s <- read_source(spec_prior_court_exposure$source)
render("prior_court_exposure", spec_prior_court_exposure, c(
  pick(s, "Winner $\\times$ Post &", 3:4, se = TRUE),
  pick(s, "Previously Represented Gov't &", 3:4, label = "Prior government work", se = TRUE),
  pick(s, "Winner $\\times$ Post $\\times$", 3:4, label = "Winner $\\times$ Post $\\times$ Prior work", se = TRUE),
  pick(s, "Observations", 3:4)))
s <- read_source(spec_withdrawal_coding$source)
lines <- strsplit(s, "\n", fixed = TRUE)[[1]]
pa <- grep("Panel A.", lines, fixed = TRUE)[1]; pb <- grep("Panel B.", lines, fixed = TRUE)[1]
panel <- paste(lines[seq.int(pa + 1L, pb - 1L)], collapse = "\n")
render("withdrawal_coding", spec_withdrawal_coding, c(pick(panel, "Treatment $\\times$ Post", 1:4, se = TRUE), pick(panel, "Sample mean", 1:4), pick(panel, "Observations", 1:4)))
layout_copy("multiple_testing", "family_wise_pvalues_appendix_table.tex",
  replacements = list(c("Family-Wise Adjusted $p$-values across the Headline Outcomes", "Adjusted $p$-values for the Original Outcome Families")),
  remove_prefixes = c("Reasoning Share &", "log(Reasoning Length + 1) &", "log(Reasoning Length) &"))
p <- file.path(dest, "multiple_testing.tex"); text <- paste(readLines(p, warn = FALSE), collapse = "\n")
text <- gsub("\\item \\textit{Note:}", "\\item \\textit{Note:} Adjustments retain the original, broader families; omitted text-length rows have not been removed from the adjustment calculation. These adjustments do not cover every newly added supplementary outcome.", text, fixed = TRUE)
writeLines(text, p, useBytes = TRUE)
manifest$output_md5[manifest$output == "multiple_testing.tex"] <- unname(tools::md5sum(p))
layout_copy("court_overlap", "firm_sutva_same_court_spillover_table.tex",
  replacements = list(c("SUTVA Diagnostic: Pre-Award Court Overlap among Winners and Comparison Firms", "Comparison Firms and Court Overlap before the Award")),
  remove_prefixes = c("Reasoning Share &", "log Reasoning Length &"))
layout_copy("descriptives", "summary_statistics_appendix_table.tex")
layout_copy("balance", "pre_procurement_balance_appendix_table.tex")
layout_copy("adoption_hazard", "city_year_adoption_hazard_table.tex")
if (file.exists(file.path(src, "city_year_disclosure_weighted_appendix_table.tex"))) {
layout_copy("disclosure_weights", "city_year_disclosure_weighted_appendix_table.tex", replacements = list(c("Disclosure-Weighted Robustness for the City-Year Administrative Estimates", "Sensitivity to Weighting by Reconstructed Docket Size"), c("Outcome & Government Win Rate & Government Win Rate & Appeal Rate & Appeal Rate & Administrative Cases & Administrative Cases", "Outcome & Gov. win & Gov. win & Appeal & Appeal & Case count & Case count"), c("Disclosure-inverse weight", "Docket-size weight")), note = "Even columns weight each city-year by the sum of inverse disclosure shares in its court-year-procedure cells. The estimated total in a cell is $\\widehat K=\\max\\{n,(n+1)m/n-1\\}$, where $n$ is the observed count and $m$ the maximum serial number; inverse shares are capped at 20. For serial-number approaches, see \\textcite{wu2022augmenting}. The sample is 2014--2020. This reweights city-years without recovering unpublished outcomes within them. Controls follow the main city specifications; standard errors are clustered by city. $^{*}p<0.10$, $^{**}p<0.05$, $^{***}p<0.01$.")
} else {
  writeLines(c("% Generated by code/build_manuscript_exhibits.R", "\\begin{table}[!htbp]", "\\centering", "\\caption{Disclosure Weighting: Required Data Unavailable}", "\\label{tab:city_year_disclosure_weighted}", "\\begin{tabular}{lp{0.72\\textwidth}}", "\\toprule", row_text(c("Status", "Explanation")), "\\midrule", row_text(c("Unavailable", "Original court filing sequences are not present. This specification cannot be estimated from the available study identifiers.")), "\\bottomrule", "\\end{tabular}", "\\end{table}"), file.path(dest, "disclosure_weights.tex"), useBytes = TRUE)
  record("disclosure_weights", "disclosure_weighting_not_applicable.txt")
}
layout_copy("case_controls", "admin_case_level_lawyer_specs_appendix_table.tex", replacements = list(c("Disentangling Pre-existing and New Government Counsel in Administrative Wins", "Government Wins with Alternative Counsel Controls"), c("Outcome & Government Win & Government Win & Government Win & Government Win", "Outcome & Gov. win & Gov. win & Gov. win & Gov. win")), note = "Linear-probability estimates with court, year, and cause-group effects. All columns control for plaintiff entity status. Later columns add government counsel, its post-award interaction, and opposing-counsel terms. Procurement may change representation, so changes in these coefficients cannot separate the mechanisms. Standard errors are clustered by city and court. $^{*}p<0.10$, $^{**}p<0.05$, $^{***}p<0.01$.")
layout_copy("court_levels", "admin_cross_jurisdiction_heterogeneity_appendix_table.tex", replacements = list(c("Subsample & Basic Court & Higher / Specialized & Local Plaintiff & Non-local Plaintiff", "Subsample & Basic court & \\shortstack{Higher or\\\\specialized} & Local plaintiff & Non-local plaintiff"), c("Pre-treatment government win rate", "Pre-award win rate")))
layout_copy("contract_exit", "firm_fect_carryover_exit_table.tex", replacements = list(c("Initial-Award Spells and Carry-over after a Successor Award", "Outcomes around a Successor Initial Award"), c("Initial-award spell (treat = 1)", "Initial-award spell"), c("Civil case win rate (decisive cases)", "Civil win"), c("Average filing-to-hearing time (days)", "Days to hearing"), c("Fee-based civil win rate (decisive fee cases)", "Fee-based win")))

s <- read_source(spec_city_controls$source)
lines <- strsplit(s, "\n", fixed = TRUE)[[1]]
starts <- grep("\\textit{Outcome:", lines, fixed = TRUE)
rows <- character()
for (i in seq_along(starts)) {
  outcome <- sub(".*Outcome: ([^}]+).*", "\\1", lines[starts[i]])
  if (outcome == "Administrative cases") next
  end <- if (i < length(starts)) starts[i + 1L] - 1L else length(lines)
  panel <- paste(lines[seq.int(starts[i] + 1L, end)], collapse = "\n")
  rows <- c(rows, paste0("\\multicolumn{5}{l}{\\textit{", outcome, "}} \\\\") ,
    pick(panel, "Treatment $\\times$ Post", 1:4, se = TRUE), pick(panel, "Observations", 1:4), "\\addlinespace")
}
render("city_controls", spec_city_controls, rows)
s <- read_source(spec_alternative_estimators$source)
lines <- strsplit(s, "\n", fixed = TRUE)[[1]]
pos <- which(startsWith(lines, "Treatment $\\times$ Post"))
vals <- line_cells(lines[pos]); ses <- line_cells(lines[pos + 1L]); rows <- character()
for (i in 1:3) {
  indices <- (i - 1L) * 3L + (1:3) + 1L
  rows <- c(rows, row_text(c(c("Government win", "Appeal", "Recorded cases")[i], vals[indices])), row_text(c("", ses[indices])))
}
render("alternative_estimators", spec_alternative_estimators, rows)
s <- read_source(spec_firm_expansion$source); clients <- read_source("firm_client_counts_table.tex")
rows <- character()
for (prefix in c("Winner $\\times$ Post", "Winner pre-award mean", "Observations")) {
  a <- pick(s, prefix, c(1, 3, 5), se = startsWith(prefix, "Winner $"))
  b <- pick(clients, prefix, 1:2, se = startsWith(prefix, "Winner $"))
  for (i in seq_along(a)) {
    ac <- line_cells(a[i]); bc <- line_cells(b[i])
    rows <- c(rows, row_text(c(ac[1:2], bc[2:3], ac[3:4])))
  }
}
render("firm_expansion", spec_firm_expansion, rows, c(spec_firm_expansion$source, "firm_client_counts_table.tex"))
write.csv(manifest, file.path(dest, "table_sources.csv"), row.names = FALSE, fileEncoding = "UTF-8")
cat("Built", length(unique(manifest$output)), "manuscript tables from R estimation outputs.\n")
